"use client";

import { useState, type SubmitEvent } from "react";
import Icon from "@/components/ui/icon";
import { useLoginMutation } from "@/hooks/use-login-mutation";

export default function LoginForm() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const loginMutation = useLoginMutation();

  const handleSubmit = (event: SubmitEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!email.trim() || !password || loginMutation.isPending) return;
    loginMutation.mutate({ email: email.trim(), password });
  };

  return (
    <form className="space-y-4" onSubmit={handleSubmit}>
      <div>
        <label htmlFor="login-email" className="mb-1 block text-sm font-semibold">이메일</label>
        <div className="flex items-center gap-2 rounded-lg border border-[#e1e4ea] bg-white px-3 focus-within:border-[#4a60df]">
          <Icon name="mail" size={16} />
          <input
            id="login-email"
            type="email"
            autoComplete="username"
            value={email}
            onChange={(event) => setEmail(event.target.value)}
            placeholder="name@example.com"
            className="h-12 min-w-0 flex-1 text-sm outline-none placeholder:text-gray-400"
          />
        </div>
      </div>
      <div>
        <label htmlFor="login-password" className="mb-1 block text-sm font-semibold">비밀번호</label>
        <div className="flex items-center gap-2 rounded-lg border border-[#e1e4ea] bg-white px-3 focus-within:border-[#4a60df]">
          <Icon name="lock" size={16} />
          <input
            id="login-password"
            type="password"
            autoComplete="current-password"
            value={password}
            onChange={(event) => setPassword(event.target.value)}
            placeholder="비밀번호"
            className="h-12 min-w-0 flex-1 text-sm outline-none placeholder:text-gray-400"
          />
        </div>
      </div>
      <button
        type="submit"
        disabled={loginMutation.isPending}
        className="h-12 w-full rounded-lg bg-[#4a60df] text-sm font-semibold text-white hover:bg-indigo-700 disabled:opacity-50"
      >
        {loginMutation.isPending ? "로그인 중" : "로그인"}
      </button>
    </form>
  );
}
